import com.sun.net.httpserver.HttpServer;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
public class Main {
  public static void main(String[] args) throws Exception {
    var server = HttpServer.create(new InetSocketAddress("127.0.0.1", 8088), 0);
    server.createContext("/health", exchange -> {
      int status = !exchange.getRequestURI().getPath().equals("/health") ? 404 : exchange.getRequestMethod().equals("GET") ? 200 : 405;
      byte[] body = (status == 200 ? "ready" : "unsupported request").getBytes(StandardCharsets.UTF_8);
      exchange.getResponseHeaders().set("Content-Type", "text/plain; charset=utf-8");
      exchange.sendResponseHeaders(status, body.length);
      try (var output = exchange.getResponseBody()) { output.write(body); }
    });
    server.start();
  }
}

public class Main {
  record Entry(String topic, int minutes) {}
  static Entry validate(String topic, int minutes) {
    if (topic == null || topic.isBlank() || topic.strip().length() > 120)
      throw new IllegalArgumentException("Topic must contain 1–120 characters");
    if (minutes < 1 || minutes > 240)
      throw new IllegalArgumentException("Minutes must be between 1 and 240");
    return new Entry(topic.strip(), minutes);
  }
  public static void main(String[] args) {
    System.out.println(validate(" Java ", 30));
  }
}

CREATE TABLE study_entry (
  id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  owner_id BIGINT NOT NULL,
  topic TEXT NOT NULL CHECK (length(trim(topic)) BETWEEN 1 AND 120),
  minutes INTEGER NOT NULL CHECK (minutes BETWEEN 1 AND 240)
);
