static void add(java.sql.Connection connection, long ownerId, String topic, int minutes) throws java.sql.SQLException {
  try (var statement = connection.prepareStatement(
      "INSERT INTO study_entry(owner_id, topic, minutes) VALUES (?, ?, ?)")) {
    statement.setLong(1, ownerId);
    statement.setString(2, topic);
    statement.setInt(3, minutes);
    statement.executeUpdate();
  }
}
