public class Main {
  static int total(int a, int b) {
    if (a < 0 || b < 0) throw new IllegalArgumentException();
    return a + b;
  }
  public static void main(String[] args) {
    if (total(20, 30) != 50) throw new AssertionError("sum");
    boolean rejected = false;
    try { total(-1, 30); } catch (IllegalArgumentException e) { rejected = true; }
    if (!rejected) throw new AssertionError("negative accepted");
    System.out.println("2 checks passed");
  }
}

